import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const effectsOf = async (h: any, p: string) => (await h.pendingEffects()).filter((e: any) => e.from === p);

test('authorize, approve, capture, refund', async () => {
  const h: any = await createHost();
  assert.deepEqual(await h.payment('p'), null);
  assert.equal((await h.capture('p', 1)).ok, false);
  assert.equal((await h.authorize('p', 3)).ok, false);
  assert.equal(await h.payment('p'), null);
  assert.deepEqual(await h.authorize('p', 2), { ok: true });
  assert.equal((await h.authorize('p', 1)).ok, false);
  const effs = await effectsOf(h, 'p');
  assert.equal(effs.length, 1);
  assert.equal(effs[0].kind, 'card.authorize');
  assert.deepEqual(effs[0].data, { amount: 2 });
  await h.completeEffect(effs[0].id, 'ok');
  assert.equal((await h.pendingEffects()).length, 0);
  assert.equal((await h.payment('p')).status, 'authorized');
  assert.equal((await h.capture('p', 2)).ok, true);
  assert.equal((await h.refund('p', 1)).ok, true);
  assert.equal((await h.refund('p', 2)).ok, false);
  assert.equal((await h.refund('p', 1)).ok, true);
  assert.deepEqual(await h.payment('p'), { status: 'refunded', authorized: 2, captured: 2, refunded: 2, requests: 1 });
  await h.__dispose();
});

test('increase', async () => {
  const h: any = await createHost();
  assert.equal((await h.increase('x')).ok, false);
  await h.authorize('x', 2);
  assert.equal((await h.increase('x')).ok, false);
  await h.completeEffect((await effectsOf(h, 'x'))[0].id, 'ok');
  assert.equal((await h.capture('x', 3)).ok, false);
  assert.equal((await h.increase('x')).ok, true);
  assert.equal((await h.increase('x')).ok, false);
  assert.equal((await h.payment('x')).authorized, 3);
  assert.equal((await h.capture('x', 4)).ok, false);
  assert.equal((await h.capture('x', 3)).ok, true);
  assert.equal((await h.increase('x')).ok, false);
  assert.equal((await h.refund('x', 3)).ok, false);
  assert.equal((await h.refund('x', 2)).ok, true);
  assert.equal((await h.refund('x', 2)).ok, false);
  assert.equal((await h.refund('x', 1)).ok, true);
  assert.deepEqual(await h.payment('x'), { status: 'refunded', authorized: 3, captured: 3, refunded: 3, requests: 1 });
  await h.__dispose();
});

test('timeouts, late answers, failure, decline, void', async () => {
  const h: any = await createHost();
  await h.authorize('a', 1);
  assert.equal((await h.timedOut('a')).ok, true);
  assert.equal((await h.timedOut('a')).ok, true);
  assert.equal((await effectsOf(h, 'a')).length, 3);
  assert.equal((await h.timedOut('a')).ok, true);
  assert.deepEqual(await h.payment('a'), { status: 'failed', authorized: 1, captured: 0, refunded: 0, requests: 3 });
  assert.equal((await h.timedOut('a')).ok, false);
  const [e] = await effectsOf(h, 'a');
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.payment('a')).status, 'failed');

  await h.authorize('b', 2);
  await h.timedOut('b');
  const bs = await effectsOf(h, 'b');
  await h.completeEffect(bs[1].id, 'failed');
  assert.equal((await h.payment('b')).status, 'declined');
  await h.completeEffect(bs[0].id, 'ok');
  assert.equal((await h.payment('b')).status, 'declined');

  await h.authorize('c', 1);
  await h.completeEffect((await effectsOf(h, 'c'))[0].id, 'ok');
  assert.equal((await h.capture('c', 2)).ok, false);
  assert.equal((await h.void('c')).ok, true);
  assert.equal((await h.capture('c', 1)).ok, false);
  assert.equal((await h.payment('c')).status, 'voided');
  await h.__dispose();
});

